/** Get pre-computed water route between two ports (by 0-based index). */
export const getRoute = (fromIdx: number, toIdx: number): Position[] | null => {
  const flat = R[`${fromIdx},${toIdx}`];
  if (!flat) return null;
  const path: Position[] = [];
  for (let i = 0; i < flat.length; i += 2) {
    path.push({ x: flat[i], y: flat[i + 1] });
  }
  return path;
};

/** Number of ports in the route table. */
export const ROUTE_PORT_COUNT = 130;
